<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\AssignmentService;use App\Services\OfferService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('ASSIGNMENT_CREATE');$offerId=(int)($_GET['offer_id']??0);$o=OfferService::operationsFind($offerId);if(!$o||$o['offer_status']!=='accepted'){http_response_code(404);exit('Accepted offer not found.');}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{$id=AssignmentService::assign($offerId,(int)Auth::user()['id'],(string)($_POST['note']??''));header('Location: '.Url::to('operations/assignment-view.php?id='.$id.'&created=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}}$pageTitle='Confirm Assignment';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Confirm assignment</h1><p><?=h($o['load_ref'].' · '.$o['origin_city'].' → '.$o['destination_city'])?></p></div><span class="badge">Accepted offer</span></div><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><div class="grid"><div class="card"><h3>Carrier</h3><p><?=h($o['carrier_company_name']?:$o['carrier_user_name'])?></p></div><div class="card"><h3>Resource</h3><p><?=h($o['registration_number'].' · '.$o['make_name'].' '.$o['model_name'])?></p><p><?=h('Driver '.$o['driver_name'])?></p></div><div class="card"><h3>Accepted price</h3><p>TZS <?=h(number_format((float)$o['offered_amount_tzs'],2))?></p><p>USD <?=h(number_format((float)$o['offered_amount_usd'],2))?></p></div></div><form method="post" class="card" style="margin-top:18px"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><div class="field"><label>Optional assignment note</label><textarea name="note" maxlength="2000" rows="4"></textarea></div><div class="notice">This creates the assignment, changes the load from approved to assigned, and keeps the selected resources reserved. It does not dispatch or create a trip.</div><button class="button">Confirm assignment</button></form><?php require BASE_PATH.'/app/Views/layout/footer.php';
